          longDescription:'This course follows the KICD Grade 10 English curriculum design. It is organised strand by strand: each strand opens with an overview and its learning outcomes, and every sub-strand has three lessons followed by a quiz, an assignment, a revision page and a summary. Every lesson includes learning outcomes and objectives, a key inquiry question, a teacher explanation, vocabulary cards with pronunciation, synonyms, antonyms and word families, language notes, listening, speaking, reading and writing activities, a grammar focus, communication skills, step-by-step examples, guided practice, pair, group and independent activities, CBC competencies, values and PCIs, common mistakes, teacher tips, exam tips, interactive questions, practice exercises, homework, reflection, a glossary and a 10-question quiz with explanations. All listening and reading texts are original and set in Kenyan contexts.',
