    <p>Your school radio club is producing a series called <em>Sauti ya Mazingira</em> (Voice of the Environment). Each episode is a natural conversation between a presenter and one or two guests — for example, a farmer, a student, a health worker or an elder — about one local climate problem such as drought, floods, deforestation or charcoal burning.</p>
