    <p style="font-size:16px;"><strong style="color:#fde68a;">The big idea:</strong> Good conversation depends on clear sounds, well-signposted ideas and vivid language: pronounce vowels accurately, guide listeners with discourse markers and bring descriptions to life with sound words.</p>
